window.kbPageData["views/entry/k-fdb33b9733777e9e"] = {"key":"entry/k-fdb33b9733777e9e","state":{"route":"entry/k-fdb33b9733777e9e"},"node":{"id":"k-fdb33b9733777e9e","mode":"k","title":"高质量发展","type":"概念与词义","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":["国考 2023 地市级 行测#4"],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"专题":["innovation"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["政治理论","科技"],"来源主题":["发展与治理"],"资料类别":["非时政"]},"directorySummary":"高质量发展是体现创新、协调、绿色、开放、共享的新发展理念，能够更好满足人民日益增长的美好生活需要的发展。《习近平经济思想学习纲要》把推动高质量发展概括为我国经济发展的鲜明主题。","review":{"definition":"高质量发展是体现创新、协调、绿色、开放、共享的新发展理念，能够更好满足人民日益增长的美好生活需要的发展。《习近平经济思想学习纲要》把推动高质量发展概括为我国经济发展的鲜明主题。","explanation":"②判断的是推动高质量发展在我国经济发展中的定位，其与《习近平经济思想学习纲要》中的“鲜明主题”对应，因此成立。③所说的“指导原则”对应坚持新发展理念。","references":[],"evidence":"推动高质量发展是我国经济发展的鲜明主题","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"b1849da23e5bae07","label":"高质量发展","topic":"发展与治理","category":"非时政","text":"1.高质量发展\n高质量发展是能够满足人民日益增长的美好生活需要的发展，是体现新发展理念的发\n展，是创新成为第一动力、协调成为内生特点、绿色成为普遍形态、开放成为必由之路、\n共享成为根本目的的发展。\n习近平总书记在党的二十大报告中强调，“高质量发展是全面建设社会主义现代化国家\n的首要任务。发展是党执政兴国的第一要务。没有坚实的物质技术基础，就不可能全面建成\n社会主义现代化强国。”","source":{"doc":"6cbfb01fe723bba64b75","first":27,"last":27,"page":27,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"国考 2023 地市级 行测#4":{"paper":"国考 2023 地市级 行测","n":4,"mod":"常识判断","src":["64bc3a15d27a04e94940.pdf",1],"asrc":["f3ab652d8e31c5bbdabc.pdf",2],"card":"62e6c598bc157bb0c0fe57d0","links":[{"id":"k-fdb33b9733777e9e","role":"直接考查","why":"题目考查推动高质量发展在我国经济发展中的主题定位。"}]}},"terms":{},"references":{},"topics":[{"slug":"innovation","title":"科技创新与科研组织"}],"units":{"k-fdb33b9733777e9e":[["国考 2023 地市级 行测#4"]]}};
